/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to Auto charges and add entry to Price Change tracking table 
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeEvent))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, AutoChargeEnabled))]
public class METPriceChangeEventAutoChargeEnabled extends METPriceChangeEvent
{
    MarkupAutoTable         markupAutoTable;
    RecordInsertList        priceChangeTrackingList;
    
}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void initInstance(Common _common, SysAppCRUDOperation _crud)
{
    this.setInternals(_Common, _crud);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void setInternals(Common _common, SysAppCRUDOperation _crud)
{
    super(_common, _crud);
    markupAutoTable = _common as MarkupAutoTable;
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::AutoChargeEnabled;
}

    /// <summary>
    /// Process the base record that triggered the change and create Price Change Track record
    /// </summary>
    public void process()
    {
        priceChangeTrackingList = new RecordInsertList(tableNum(METPriceChangeTracking));

        if(markupAutoTable.ModuleCategory == HeadingLine::Heading)
        {
            this.processHeaderCharge();
        }
        else if(markupAutoTable.ModuleCategory == HeadingLine::Line)
        {
            this.processLineCharge();
        }
        
        ttsbegin;
        priceChangeTrackingList.insertDatabase();
        ttscommit;
    }

    /// <summary>
    /// Process Line type Auto charge
    /// </summary>
    public void processHeaderCharge()
    {
        MarkupAutoLine  markupAutoLine;

        while select markupAutoLine
            where   markupAutoLine.TableRecId       == markupAutoTable.recid
            &&      markupAutoLine.TableTableId     == markupAutoTable.TableId
            &&     (markupAutoLine.MarkupCategory   == MarkupCategory::Percent || markupAutoLine.MarkupCategory   == MarkupCategory::Pcs)
        {
            this.processSimple(markupAutoLine);
        }
    }

    /// <summary>
    /// Process Header type Auto charge
    /// </summary>
    public void processLineCharge()
    {
        MarkupAutoLine  markupAutoLine;

        while select markupAutoLine
            where   markupAutoLine.TableRecId       == markupAutoTable.recid
            &&      markupAutoLine.TableTableId     == markupAutoTable.TableId
        {
            this.processSimple(markupAutoLine);
        }
    }

    /// <summary>
    /// Process the base record that triggered the change and create Price Change Track record
    /// </summary>
    /// <param name = "_markupAutoLine">Markup line</param>
    public void processSimple(MarkupAutoLine  _markupAutoLine)
    {
        FromDate                    fromDate;
        RetailQtyLowest             fromQty;

        fromDate = this.getFromDate(_markupAutoLine.FromDate);
        fromQty = this.getFromQty(_markupAutoLine.FromAmount);

        this.cleanup(fromDate, fromQty, _markupAutoLine);
        this.processTrans(fromDate, fromQty, _markupAutoLine);
        priceChangeTrackingList.add(priceChangeTracking);

    }

/// <summary>
/// Process the base record that triggered the change and create Price Change Track record
/// </summary>
/// <param name = "_fromDate">From Date</param>
/// <param name = "_fromQty">From Quantity</param>
/// <param name = "_markupAutoLine">Markup line</param>
public void processTrans(FromDate _fromDate, RetailQtyLowest _fromQty, MarkupAutoLine _markupAutoLine)
{
    priceChangeTracking.clear();
    this.setCommonValues(_markupAutoLine);
    priceChangeTracking.ChargeCodeDescription   = markupAutoTable.Description;
    priceChangeTracking.ChargeCodeLineNum       = _markupAutoLine.lineNum;
    priceChangeTracking.PriceComponentCode      = markupAutoTable.PriceComponentCodeName;
    priceChangeTracking.PricingRuleHeader       = _markupAutoLine.pricingRuleHeader ? _markupAutoLine.pricingRuleHeader : markupAutoTable.PricingRuleHeader;
    priceChangeTracking.PricingRuleLine         = _markupAutoLine.PricingRuleLine ? _markupAutoLine.PricingRuleLine : markupAutoTable.PricingRuleLine;
    priceChangeTracking.Activation              = NoYes::Yes;
    priceChangeTracking.QuantityAmountFrom      = _fromQty;
    priceChangeTracking.FromDate                = _fromDate;
    priceChangeTracking.InventSiteId            = _markupAutoLine.InventSiteId;
    priceChangeTracking.ChargeCodeModuleCategory = markupAutoTable.ModuleCategory;
}

/// <summary>
/// remove existing records to avoid duplicate processing and churn
/// </summary>
/// <param name = "_fromDate">from date</param>
/// <param name = "_fromQty">qty from</param>
/// <param name = "_markupAutoLine">Markup line</param>
public void cleanup(FromDate _fromDate, RetailQtyLowest _fromQty, MarkupAutoLine _markupAutoLine)
{
    METPriceChangeTracking      priceChangeTrackingLoc;
    
    //if a record of the same type exists remove it.
    ttsbegin;
    
    delete_from priceChangeTrackingLoc
        where   priceChangeTrackingLoc.ChargeCodeDescription == markupAutoTable.Description
        &&      priceChangeTrackingLoc.ChargeCodeLineNum    == _markupAutoLine.LineNum
        &&      priceChangeTrackingLoc.PriceComponentCode   == markupAutoTable.PriceComponentCodeName
        &&      priceChangeTrackingLoc.FromDate             == _fromDate
        &&      priceChangeTrackingLoc.QuantityAmountFrom   == _fromQty
        &&      priceChangeTrackingLoc.ChangeType           == METPriceChangeType::AutoChargeEnabled
        &&      priceChangeTrackingLoc.Activation           == NoYes::Yes;

    ttscommit;
}
